using UnityEngine;
public class BBBWolfCharacterReview : MonoBehaviour {
 public BBBWolfCharacter character;
 public float yaw=180;
 void OnGUI(){GUILayout.BeginArea(new Rect(16,16,280,680),GUI.skin.box);GUILayout.Label("BUY, BID, BLOW / CHARACTER");GUILayout.Label("Expression");character.expression=(BBBWolfCharacter.Face)GUILayout.SelectionGrid((int)character.expression,new[]{"Happy","Suspicious","Shocked","Blank bluff"},2);GUILayout.Label("Outfit");character.upper=GUILayout.SelectionGrid(character.upper,new[]{"Suit","Shirt","Vest"},3);character.lower=GUILayout.SelectionGrid(character.lower,new[]{"Long","Shorts"},2);GUILayout.Label("Animation");int next=GUILayout.SelectionGrid(character.action,character.actionLabels,1);if(next!=character.action)character.PlayAction(next);character.animate=GUILayout.Toggle(character.animate,"Play animation");float phase=GUILayout.HorizontalSlider(character.phase,0,.999f);if(phase!=character.phase){character.phase=phase;character.Sample();}GUILayout.Label("Rotate");yaw=GUILayout.HorizontalSlider(yaw,0,360);character.model.localRotation=Quaternion.Euler(0,yaw,0);GUILayout.BeginHorizontal();if(GUILayout.Button("Red"))character.SetTieColor(new Color(.54f,.16f,.22f));if(GUILayout.Button("Blue"))character.SetTieColor(new Color(.13f,.32f,.65f));if(GUILayout.Button("Gold"))character.SetTieColor(new Color(.82f,.61f,.12f));GUILayout.EndHorizontal();character.ApplyAppearance();GUILayout.EndArea();}
}
